#!/usr/bin/env node
/**
 * Creates Kitty's QuickNode Stream (or lists streams with --list).
 *
 *   node apps/onboard/scripts/create-stream.mjs [--list] [--dry-run]
 *
 * Reads QUICKNODE_API_KEY, TREASURY_ADDRESS and TREASURY_DEPLOY_BLOCK from apps/server/.env.
 * Optional: QN_STREAM_SECRET (32+ chars; generated by QuickNode if unset), QN_NETWORK (default arc-testnet), QN_BATCH_SIZE (default 5),
 * STREAM_WEBHOOK_URL (default https://kittyagent.vercel.app/api/stream).
 * Prints the stream id and its security token: put the token in Vercel as QN_STREAM_SECRET.
 */
import { readFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const serverEnv = join(here, "../../server/.env");
if (existsSync(serverEnv)) process.loadEnvFile(serverEnv);

const API = "https://api.quicknode.com/streams/rest/v1/streams";
const key = process.env.QUICKNODE_API_KEY;
if (!key) {
  console.error("Set QUICKNODE_API_KEY in apps/server/.env");
  process.exit(1);
}
const headers = { "x-api-key": key, "content-type": "application/json", accept: "application/json" };

if (process.argv.includes("--list")) {
  const res = await fetch(API, { headers });
  const body = await res.json().catch(() => ({}));
  const streams = Array.isArray(body) ? body : (body.data ?? []);
  if (!res.ok) {
    console.error(`HTTP ${res.status}`, body);
    process.exit(1);
  }
  for (const s of streams) console.log(`${s.id}  ${s.status}  ${s.network}  ${s.dataset}  ${s.name}`);
  if (!streams.length) console.log("no streams");
  process.exit(0);
}

const treasury = process.env.TREASURY_ADDRESS ?? "";
const startBlock = Number(process.env.TREASURY_DEPLOY_BLOCK ?? "");
if (!/^0x[0-9a-fA-F]{40}$/.test(treasury) || !Number.isInteger(startBlock)) {
  console.error("Set TREASURY_ADDRESS and TREASURY_DEPLOY_BLOCK in apps/server/.env");
  process.exit(1);
}

const filter = readFileSync(join(here, "../streams/filter.js"), "utf8").replaceAll("__TREASURY__", treasury);
const body = {
  name: `kitty-treasury-${treasury.slice(2, 8).toLowerCase()}`,
  network: process.env.QN_NETWORK ?? "arc-testnet",
  dataset: "block_with_receipts",
  filter_function: Buffer.from(filter).toString("base64"),
  region: "usa_east",
  start_range: startBlock,
  end_range: -1,
  dataset_batch_size: Number(process.env.QN_BATCH_SIZE ?? 5),
  elastic_batch_enabled: true,
  fix_block_reorgs: 1,
  keep_distance_from_tip: 0,
  destination: "webhook",
  destination_attributes: {
    url: process.env.STREAM_WEBHOOK_URL ?? "https://kittyagent.vercel.app/api/stream",
    compression: "none",
    max_retry: 10,
    retry_interval_sec: 3,
    post_timeout_sec: 20,
    // Our own token when set, so it can go into Vercel before the first delivery.
    ...(process.env.QN_STREAM_SECRET ? { security_token: process.env.QN_STREAM_SECRET } : {}),
  },
  status: "active",
};

if (process.argv.includes("--dry-run")) {
  console.log(JSON.stringify({ ...body, filter_function: `<${filter.length} chars, base64>` }, null, 2));
  process.exit(0);
}

const res = await fetch(API, { method: "POST", headers, body: JSON.stringify(body) });
const created = await res.json().catch(() => ({}));
if (!res.ok) {
  console.error(`HTTP ${res.status}`, JSON.stringify(created, null, 2));
  process.exit(1);
}
const stream = created.data ?? created;
console.log(`stream ${stream.id} (${stream.status}) on ${stream.network}, from block ${startBlock}`);
const token = stream.destination_attributes?.security_token;
if (process.env.QN_STREAM_SECRET) console.log("security token: QN_STREAM_SECRET from apps/server/.env");
else console.log(token ? `security token: ${token}\n-> set it in Vercel as QN_STREAM_SECRET` : "no security token in the reply; copy it from the QuickNode dashboard");
